head.b:skin:
/* ==========================================================================
   Ankita Pandey - Blogger XML Portfolio Theme (Luminous Sunset Aura Edition)
   ========================================================================== */

:root {
    --bg-main: #FAFAFC;
    --bg-surface: rgba(255, 255, 255, 0.85);
    --bg-surface-elevated: #FFFFFF;
    --bg-glass: rgba(255, 255, 255, 0.8);
    --border-light: rgba(15, 23, 42, 0.08);
    --text-primary: #0F172A;
    --text-secondary: #475569;
    --text-muted: #64748B;
    --accent-orange: #FF5E36;
    --accent-purple: #8B5CF6;
    --accent-emerald: #10B981;
    --font-heading: 'Instrument Serif', Georgia, serif;
    --font-sans: 'Plus Jakarta Sans', -apple-system, sans-serif;
    --font-ui: 'Outfit', sans-serif;
    --shadow-glass: 0 20px 40px -15px rgba(15, 23, 42, 0.07);
    --shadow-glow: 0 15px 35px rgba(255, 94, 54, 0.2);
    --transition-smooth: 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    --transition-fast: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body { background-color: var(--bg-main); color: var(--text-primary); font-family: var(--font-sans); line-height: 1.6; overflow-x: hidden; }

/* Hide standard Blogger navbar elements if present */
.navbar-blogger, #b-navbar, .widget-content { display: none !important; }
#main { display: none !important; }

/* Sunset Aura Mesh Backdrop */
.aura-container { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; overflow: hidden; z-index: -1; pointer-events: none; }
.aura-blob { position: absolute; border-radius: 50%; filter: blur(100px); opacity: 0.65; animation: auraFloat 20s infinite ease-in-out alternate; }
.aura-blob-1 { top: -10%; left: 20%; width: 600px; height: 600px; background: radial-gradient(circle, #FF5E36 0%, #FF9F43 60%, transparent 100%); }
.aura-blob-2 { top: 15%; right: -10%; width: 700px; height: 700px; background: radial-gradient(circle, #8B5CF6 0%, #EC4899 60%, transparent 100%); animation-delay: -5s; }
.aura-blob-3 { bottom: -10%; left: -10%; width: 650px; height: 650px; background: radial-gradient(circle, #38BDF8 0%, #8B5CF6 60%, transparent 100%); animation-delay: -10s; }
@keyframes auraFloat {
    0% { transform: translate(0, 0) scale(1) rotate(0deg); }
    50% { transform: translate(60px, 40px) scale(1.1) rotate(180deg); }
    100% { transform: translate(-40px, 80px) scale(0.95) rotate(360deg); }
}

.container { max-width: 1200px; margin: 0 auto; padding: 0 2rem; }
.glass-card { background: var(--bg-surface); border: 1px solid var(--border-light); border-radius: 20px; padding: 2.25rem; backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); box-shadow: var(--shadow-glass); transition: var(--transition-smooth); }
.glass-card:hover { border-color: rgba(255, 94, 54, 0.3); transform: translateY(-4px); box-shadow: 0 25px 50px -12px rgba(255, 94, 54, 0.12); }

.btn { display: inline-flex; align-items: center; justify-content: center; gap: 0.6rem; padding: 0.85rem 1.85rem; font-family: var(--font-ui); font-size: 0.95rem; font-weight: 600; border-radius: 999px; text-decoration: none; cursor: pointer; transition: var(--transition-smooth); border: none; }
.btn-primary { background: linear-gradient(135deg, #FF5E36 0%, #FF7E5F 100%); color: #FFFFFF; box-shadow: var(--shadow-glow); }
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 18px 35px rgba(255, 94, 54, 0.35); }
.btn-secondary { background: #FFFFFF; color: var(--text-primary); border: 1px solid var(--border-light); }
.btn-secondary:hover { border-color: var(--accent-orange); color: var(--accent-orange); transform: translateY(-2px); }

.tag { display: inline-flex; align-items: center; gap: 0.35rem; padding: 0.35rem 0.85rem; border-radius: 999px; font-family: var(--font-ui); font-size: 0.8rem; font-weight: 600; background: rgba(15, 23, 42, 0.04); border: 1px solid var(--border-light); color: var(--text-secondary); }
.tag-orange { background: rgba(255, 94, 54, 0.08); border-color: rgba(255, 94, 54, 0.25); color: #E04823; }
.tag-purple { background: rgba(139, 92, 246, 0.08); border-color: rgba(139, 92, 246, 0.25); color: #7C3AED; }

/* Navigation */
.navbar { position: fixed; top: 1.25rem; left: 50%; transform: translateX(-50%); width: min(92%, 1160px); z-index: 1000; background: var(--bg-glass); border: 1px solid var(--border-light); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border-radius: 999px; padding: 0.75rem 1.75rem; display: flex; align-items: center; justify-content: space-between; box-shadow: 0 10px 30px rgba(15, 23, 42, 0.05); }
.nav-brand { display: flex; align-items: center; gap: 0.75rem; text-decoration: none; }
.brand-avatar { width: 36px; height: 36px; border-radius: 50%; background: linear-gradient(135deg, #FF5E36, #8B5CF6); display: flex; align-items: center; justify-content: center; font-family: var(--font-ui); font-weight: 700; color: #FFFFFF; font-size: 0.85rem; }
.brand-title { font-family: var(--font-ui); font-weight: 700; font-size: 1.05rem; color: var(--text-primary); }
.nav-links { display: flex; align-items: center; gap: 1.75rem; list-style: none; }
.nav-links a { color: var(--text-secondary); text-decoration: none; font-family: var(--font-ui); font-size: 0.9rem; font-weight: 500; transition: var(--transition-fast); }
.nav-links a:hover, .nav-links a.active { color: var(--accent-orange); }

/* Hero */
.hero { padding-top: 11rem; padding-bottom: 6rem; text-align: center; position: relative; }
.hero-content-centered { max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; align-items: center; }
.hero-main-title { font-family: var(--font-heading); font-size: clamp(3.2rem, 7vw, 5.8rem); line-height: 1.05; margin-bottom: 1.5rem; font-weight: 400; letter-spacing: -0.02em; }
.hero-sub-text { font-size: 1.2rem; color: var(--text-secondary); max-width: 680px; margin: 0 auto 2.5rem auto; line-height: 1.7; }
.hero-metrics-pill { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; background: #FFFFFF; border: 1px solid var(--border-light); padding: 1.5rem 2.5rem; border-radius: 24px; box-shadow: var(--shadow-glass); width: 100%; max-width: 960px; }
.metric-num { font-family: var(--font-ui); font-size: 2.2rem; font-weight: 800; background: linear-gradient(135deg, #FF5E36 0%, #8B5CF6 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; display: block; line-height: 1.1; }
.metric-desc { font-size: 0.8rem; color: var(--text-muted); font-weight: 600; text-transform: uppercase; margin-top: 0.3rem; }

.section-header { text-align: center; max-width: 680px; margin: 0 auto 4rem auto; }
.section-subtitle { font-family: var(--font-ui); font-size: 0.85rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--accent-orange); margin-bottom: 0.5rem; display: block; }
.section-title { font-family: var(--font-heading); font-size: clamp(2.4rem, 4vw, 3.5rem); font-weight: 400; line-height: 1.15; margin-bottom: 0.85rem; }

/* Timeline & Grid */
.pillars-grid, .skills-grid, .projects-grid, .awards-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.timeline { position: relative; max-width: 920px; margin: 0 auto; }
.timeline::before { content: ''; position: absolute; left: 28px; top: 24px; bottom: 24px; width: 2px; background: linear-gradient(180deg, var(--accent-orange) 0%, rgba(139, 92, 246, 0.3) 100%); }
.timeline-item { position: relative; padding-left: 70px; margin-bottom: 2.5rem; }
.timeline-marker { position: absolute; left: 18px; top: 24px; width: 22px; height: 22px; border-radius: 50%; background: #FFFFFF; border: 2px solid var(--accent-orange); z-index: 2; }
.timeline-role { font-family: var(--font-ui); font-size: 1.35rem; font-weight: 700; }
.timeline-company { color: var(--accent-orange); font-weight: 600; display: block; }
.timeline-bullets { list-style: none; margin-top: 0.75rem; margin-bottom: 1.5rem; }
.timeline-bullets li { position: relative; padding-left: 1.5rem; margin-bottom: 0.6rem; color: var(--text-secondary); }
.timeline-bullets li::before { content: '✦'; position: absolute; left: 0; color: var(--accent-orange); font-size: 0.75rem; }

/* Simulator */
.simulator-container { background: #FFFFFF; border: 1px solid var(--border-light); border-radius: 28px; padding: 2.5rem; }
.simulator-steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; margin-bottom: 2rem; }
.step-card { background: var(--bg-main); border: 1px solid var(--border-light); border-radius: 14px; padding: 1.25rem; cursor: pointer; }
.step-card.active { background: #FFFFFF; border-color: var(--accent-orange); box-shadow: 0 10px 25px rgba(255, 94, 54, 0.15); }
.simulator-preview { background: var(--bg-main); border: 1px solid var(--border-light); border-radius: 20px; padding: 2rem; display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 2rem; align-items: center; }

/* Modal & Footer */
.modal-backdrop { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(15, 23, 42, 0.6); backdrop-filter: blur(12px); z-index: 2000; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: var(--transition-smooth); }
.modal-backdrop.active { opacity: 1; visibility: visible; }
.modal-container { background: #FFFFFF; border-radius: 24px; width: min(100%, 850px); max-height: 85vh; overflow-y: auto; padding: 2.5rem; position: relative; }
.footer { padding: 2.5rem 0; border-top: 1px solid var(--border-light); text-align: center; color: var(--text-muted); background: #FFFFFF; }

@media (max-width: 768px) {
    .nav-links { display: none; }
    .hero-metrics-pill, .simulator-steps, .simulator-preview { grid-template-columns: 1fr; }
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
    const modal = document.getElementById('resume-modal');
    const openBtns = [document.getElementById('open-resume-btn'), document.getElementById('open-resume-header-btn')];
    const closeBtn = document.getElementById('close-resume-btn');

    openBtns.forEach(btn => {
        if (btn) btn.addEventListener('click', () => { if(modal) modal.classList.add('active'); });
    });
    if (closeBtn && modal) closeBtn.addEventListener('click', () => modal.classList.remove('active'));
});
//
